/// The instrumentation scope: the package name and its version.
fn scope() -> InstrumentationScope {
    InstrumentationScope::builder(env!("CARGO_PKG_NAME"))
        .with_version(env!("CARGO_PKG_VERSION"))
        .build()
}

impl CallHook for OpenTelemetryCallHook {
    fn start(
        &self,
        info: &CallInfo,
        headers: &mut HashMap<String, String>,
    ) -> Option<Box<dyn CallObserver>> {
        let attributes = vec![
            KeyValue::new("http.request.method", info.method.clone()),
            KeyValue::new("url.template", info.url_template.clone()),
            KeyValue::new("server.address", info.server_address.clone()),
        ];
        let parent = Context::current();
        let span = self.tracer.build_with_context(
            self.tracer
                .span_builder(info.operation_id.clone())
                .with_kind(SpanKind::Client)
                .with_attributes(attributes.clone()),
            &parent,
        );
        let cx = parent.with_span(span);

        /* The adapter writes the W3C headers itself, after the propagated
         * context of the caller's span, so the request names the client span as
         * its parent. A span that is not recording a valid context (no provider)
         * leaves the headers alone. */
        let span_context = cx.span().span_context().clone();
        if span_context.is_valid() {
            insert_header(
                headers,
                "traceparent".to_string(),
                format!(
                    "00-{}-{}-{:02x}",
                    span_context.trace_id(),
                    span_context.span_id(),
                    span_context.trace_flags().to_u8()
                ),
            );
            let state = span_context.trace_state().header();
            if state.is_empty() {
                remove_header(headers, "tracestate");
            } else {
                insert_header(headers, "tracestate".to_string(), state);
            }
        }

        Some(Box::new(Observer {
            cx,
            attributes,
            counter: self.counter.clone(),
            duration: self.duration.clone(),
            started: Instant::now(),
        }))
    }
}

struct Observer {
    cx: Context,
    attributes: Vec<KeyValue>,
    counter: Counter<u64>,
    duration: Histogram<f64>,
    started: Instant,
}

impl CallObserver for Observer {
    fn finish(self: Box<Self>, outcome: &CallOutcome<'_>) {
        let elapsed = self.started.elapsed().as_secs_f64();
        let mut attributes = self.attributes.clone();
        if outcome.status_code != 0 {
            attributes.push(KeyValue::new(
                "http.response.status_code",
                i64::from(outcome.status_code),
            ));
        }
        let error_type = error_type_of(outcome);
        if let Some(error_type) = &error_type {
            attributes.push(KeyValue::new("error.type", error_type.clone()));
        }

        let span = self.cx.span();
        if outcome.status_code != 0 {
            span.set_attribute(KeyValue::new(
                "http.response.status_code",
                i64::from(outcome.status_code),
            ));
        }
        if let Some(error_type) = error_type {
            span.set_attribute(KeyValue::new("error.type", error_type.clone()));
            span.set_status(Status::error(error_type));
        }
        span.end();

        self.counter.add(1, &attributes);
        self.duration.record(elapsed, &attributes);
    }
}

/// The `error.type` of an outcome: the status for a status of 400 or more,
/// otherwise a token for the kind of error, and `None` on success.
fn error_type_of(outcome: &CallOutcome<'_>) -> Option<String> {
    if outcome.status_code >= 400 {
        return Some(outcome.status_code.to_string());
    }
    let error = outcome.error?;
    let token = if error.downcast_ref::<NetworkTimeoutError>().is_some() {
        "timeout"
    } else if error.downcast_ref::<NetworkError>().is_some() {
        "network_error"
    } else if error.downcast_ref::<SerializationError>().is_some() {
        "serialization_error"
    } else if error.downcast_ref::<CallCancelled>().is_some() {
        "cancelled"
    } else {
        "_OTHER"
    };
    Some(token.to_string())
}

