    #[test]
    fn test_bhv_telemetry_001_the_span_is_named_with_the_operation_id_and_has_kind_client() {
        let h = harness();
        run(&h, 200, None);

        let spans = finished(&h);
        assert_eq!(1, spans.len());
        assert_eq!("echo_operation", spans[0].name);
        assert_eq!(opentelemetry::trace::SpanKind::Client, spans[0].span_kind);
    }

    #[test]
    fn test_bhv_telemetry_002_a_2xx_sets_the_request_and_response_attributes_and_leaves_the_status_unset(
    ) {
        let h = harness();
        run(&h, 200, None);

        let span = &finished(&h)[0];
        let mut expected = HashMap::new();
        expected.insert("http.request.method".to_string(), "GET".to_string());
        expected.insert("url.template".to_string(), "/items/{id}".to_string());
        expected.insert("server.address".to_string(), "localhost".to_string());
        expected.insert("http.response.status_code".to_string(), "200".to_string());
        assert_eq!(expected, attributes(span));
        assert_eq!(opentelemetry::trace::Status::Unset, span.status);
    }

    #[test]
    fn test_bhv_telemetry_003_a_4xx_or_5xx_sets_the_status_as_error_type_and_marks_the_span_an_error(
    ) {
        for status in [404u16, 503] {
            let h = harness();
            let failure = ApiError::new(status, "failed".to_string(), None, None);
            run(&h, status, Some(&failure));

            let span = &finished(&h)[0];
            assert_eq!(
                Some(&status.to_string()),
                attributes(span).get("error.type")
            );
            assert!(
                matches!(span.status, opentelemetry::trace::Status::Error { .. }),
                "{status}"
            );
        }
    }

    #[test]
    fn test_bhv_telemetry_004_error_type_names_the_kind_of_error() {
        let timeout = NetworkTimeoutError::from(
            NetworkError::try_from(ApiError::new(0, "timed out".to_string(), None, None))
                .expect("status 0"),
        );
        let network = NetworkError::try_from(ApiError::new(0, "refused".to_string(), None, None))
            .expect("status 0");
        let decode = SerializationError::new("bad body".to_string(), None);
        let other = std::io::Error::other("something else");
        let cases: Vec<(&str, &(dyn std::error::Error + 'static))> = vec![
            ("timeout", &timeout),
            ("network_error", &network),
            ("serialization_error", &decode),
            ("cancelled", &CallCancelled),
            ("_OTHER", &other),
        ];
        for (token, error) in cases {
            let h = harness();
            run(&h, 0, Some(error));

            let span = &finished(&h)[0];
            assert_eq!(
                Some(&token.to_string()),
                attributes(span).get("error.type"),
                "{token}"
            );
            assert!(
                matches!(span.status, opentelemetry::trace::Status::Error { .. }),
                "{token}"
            );
        }
    }

    #[test]
    fn test_bhv_telemetry_005_a_call_with_no_response_sets_no_status_code() {
        let h = harness();
        let failure = network_error();
        run(&h, 0, Some(&*failure));

        assert!(!attributes(&finished(&h)[0]).contains_key("http.response.status_code"));
    }

    #[test]
    fn test_bhv_telemetry_006_the_span_is_a_child_of_the_active_span_and_the_traceparent_names_it()
    {
        let h = harness();
        let parent = h.traces.tracer("parent").start("caller");
        let parent_context = parent.span_context().clone();
        let cx = opentelemetry::Context::new().with_span(parent);
        let mut headers = HashMap::new();
        headers.insert("traceparent".to_string(), "00-stale".to_string());
        {
            let _active = cx.clone().attach();
            let observer = h.hook.start(&info(), &mut headers).expect("an observer");
            observer.finish(&CallOutcome {
                status_code: 200,
                headers: None,
                error: None,
            });
        }

        let child = &finished(&h)[0];
        assert_eq!(parent_context.span_id(), child.parent_span_id);
        assert_eq!(parent_context.trace_id(), child.span_context.trace_id());
        let names: Vec<_> = headers
            .keys()
            .filter(|k| k.eq_ignore_ascii_case("traceparent"))
            .collect();
        assert_eq!(1, names.len());
        assert_eq!(
            format!(
                "00-{}-{}-{:02x}",
                child.span_context.trace_id(),
                child.span_context.span_id(),
                child.span_context.trace_flags().to_u8()
            ),
            headers["traceparent"]
        );
    }

