    #[test]
    fn test_bhv_telemetry_011_a_provider_handed_to_the_hook_is_used_instead_of_the_global_one() {
        let h = harness();
        let global = OpenTelemetryCallHook::new();

        let mut headers = HashMap::new();
        global
            .start(&info(), &mut headers)
            .expect("an observer")
            .finish(&CallOutcome {
                status_code: 200,
                headers: None,
                error: None,
            });
        assert!(
            finished(&h).is_empty(),
            "the global hook never reaches this provider"
        );
        assert!(headers.is_empty());

        run(&h, 200, None);
        assert_eq!(1, finished(&h).len());
        assert!(!points(&h).is_empty());
    }

