    #[tokio::test]
    async fn test_bhv_telemetry_013_the_span_ends_exactly_once_also_when_the_call_fails_or_is_dropped(
    ) {
        let h = harness();
        api(&h, vec![200], false)
            .invoke_api(params())
            .await
            .expect("success");
        assert_eq!(1, finished(&h).len());

        let failed = harness();
        api(&failed, Vec::new(), true)
            .invoke_api(params())
            .await
            .expect_err("network failure");
        assert_eq!(1, finished(&failed).len());
        assert_eq!(
            Some(&"network_error".to_string()),
            attributes(&finished(&failed)[0]).get("error.type")
        );

        let dropped = harness();
        let hook: Arc<dyn CallHook> = dropped.hook.clone();
        let mut scope = CallScope::new();
        scope.begin(Some(&hook), &mut HashMap::new(), info);
        drop(scope);
        assert_eq!(1, finished(&dropped).len());
        assert_eq!(
            Some(&"cancelled".to_string()),
            attributes(&finished(&dropped)[0]).get("error.type")
        );
    }

    #[tokio::test]
    async fn test_bhv_telemetry_014_no_attribute_carries_a_query_string_a_header_value_or_a_credential(
    ) {
        let h = harness();
        api(&h, vec![200], false)
            .invoke_api(params())
            .await
            .expect("success");

        let mut values: Vec<String> = attributes(&finished(&h)[0]).into_values().collect();
        for point in points(&h) {
            values.extend(point.attributes.into_values());
        }
        assert!(!values.is_empty());
        for value in values {
            assert!(
                !value.contains("secret") && !value.contains("Bearer") && !value.contains('?'),
                "{value}"
            );
        }
    }
